using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Context;
using Harborline.Foundation.RuleEngine.Environments;
using Harborline.Foundation.RuleEngine.Standings;

namespace Harborline.Foundation.RuleEngine.Records;

/// <summary>
/// A record write a bound rule refused: the rule, and why. <see cref="Code"/> is the rule's own id when its
/// predicate is false; any other code means the rule could not be interpreted, which refuses too (L274).
/// </summary>
public sealed record RecordRuleRefusal(string RuleId, string Code);

/// <summary>
/// The Rules stage of a Records write (DES-0018 <c>rules-eng-13</c>/<c>rules-eng-14</c>, DES-0029
/// <c>kernel-core-ck-10</c>): the record-level rules one record type's active schema generation binds, bound
/// once when that generation activates and evaluated on every write after mutation and before commit.
/// </summary>
/// <remarks>
/// A record rule reuses the schema-scoped shape of <see cref="StandingRuleDefinition"/> (T-978 owner ruling,
/// 2026-09-28): a <c>harborline-jsonlogic/v1</c> validation predicate that reads only top-level record fields.
/// It reads the record and the act instant, never the principal: Rules narrows, it never decides access.
/// </remarks>
public sealed class RecordWriteRules
{
    /// <summary>
    /// The Records borrower's expression environment, as released for DES-0015 (<c>records-auth-12</c>). Records
    /// is kernel and cannot reference Rules, so its declaration row is stated here, where it is admitted.
    /// </summary>
    public static BorrowerEnvironmentDeclaration Declaration { get; } = new(
        Borrower: "records-auth-12",
        Grammar: BorrowerEnvironmentAdmission.Grammar,
        Variables: new Dictionary<string, string> { ["field"] = "record field", ["row"] = "child row", ["caller"] = "authenticated-principal" },
        Operations: ["var", "missing", "missing_some", "==", "!=", "===", "!==", "!", "!!", "and", "or", "if", ">", ">=", "<", "<=",
            "+", "-", "*", "/", "%", "min", "max", "in", "cat", "agg", "money.add", "money.sub", "money.mul", "date.add", "date.diff",
            "date.today", "coding.is"],
        Effects: [BorrowerEnvironmentAdmission.FieldRead],
        MissingValues: "missing-field-reads-null",
        TimeSource: "evaluated-at",
        TimeZone: "utc",
        Phases: new Dictionary<EvaluationPhase, bool>
        {
            [EvaluationPhase.AuthoringValidation] = false,
            [EvaluationPhase.PublishValidation] = true,
            [EvaluationPhase.Render] = false,
            [EvaluationPhase.Submission] = true,
            [EvaluationPhase.Run] = false,
            [EvaluationPhase.SignOff] = false,
        },
        Replay: "deterministic");

    /// <summary>The phase a record write evaluates in: the record is being submitted for commit.</summary>
    public const EvaluationPhase Phase = EvaluationPhase.Submission;

    private static readonly EvaluationAdmission Admission = BorrowerEnvironmentAdmission.Admit(Declaration).For(Phase);

    private readonly RuleEngineLimits _limits;

    private RecordWriteRules(string recordType, RuleDefinition[] rules, RuleEngineLimits limits)
        => (RecordType, Rules, _limits) = (recordType, rules, limits);

    /// <summary>The record type these rules bind to.</summary>
    public string RecordType { get; }

    /// <summary>The bound rules, in evaluation order (rule id, ordinal).</summary>
    public IReadOnlyList<RuleDefinition> Rules { get; }

    /// <summary>
    /// Binds <paramref name="rules"/> to <paramref name="recordType"/> when its schema generation activates.
    /// Refuses by <see cref="ArgumentException"/> a blank type, a duplicate rule id, or any rule outside the
    /// schema-scoped shape; a rule that does not compile refuses by <c>RuleCompilationException</c>.
    /// </summary>
    public static RecordWriteRules Bind(string recordType, IReadOnlyList<RuleDefinition> rules, RuleEngineLimits? limits = null)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(recordType);
        ArgumentNullException.ThrowIfNull(rules);
        foreach (var rule in rules)
        {
            ArgumentNullException.ThrowIfNull(rule);
            StandingRuleDefinition.RequireValidationShape(rule);
            _ = StandingRuleDefinition.FieldsRead(rule);
        }
        if (rules.Select(rule => rule.Id).Distinct(StringComparer.Ordinal).Count() != rules.Count)
            throw new ArgumentException("Record rule ids must be unique.", nameof(rules));
        return new(recordType, [.. rules.OrderBy(rule => rule.Id, StringComparer.Ordinal)], limits ?? RuleEngineLimits.Default);
    }

    /// <summary>
    /// Evaluates every bound rule on <paramref name="record"/>, which must be exactly the state the write will
    /// commit (L272), at the act <paramref name="instant"/>. Returns the first refusal in rule order, or
    /// <see langword="null"/> when every rule passes. Fails closed: a rule that cannot be interpreted refuses.
    /// </summary>
    public RecordRuleRefusal? Evaluate(JsonObject record, DateTimeOffset instant, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(record);
        var snapshot = RuleContextSnapshot.Capture(record.ToDictionary(field => field.Key, field => field.Value?.DeepClone()));
        var guard = new GuardEvaluator(new PinnedClock(instant), _limits);
        foreach (var rule in Rules)
        {
            var verdict = guard.EvaluateGuard(rule, snapshot, RuleEvalScope.Root, Admission, cancellationToken);
            if (!verdict.Ok) return new(rule.Id, verdict.Error?.Code ?? rule.Id);
        }
        return null;
    }

    private sealed class PinnedClock(DateTimeOffset instant) : TimeProvider
    {
        public override DateTimeOffset GetUtcNow() => instant;
    }
}

using Harborline.Foundation.RuleEngine.Compilation;

namespace Harborline.Foundation.RuleEngine.Standings;

/// <summary>A domain-declared position computed from one record type's own fields. A fact, never a role.</summary>
public readonly record struct StandingReference
{
    /// <summary>Creates a standing name.</summary>
    public StandingReference(string name)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(name);
        Name = name;
    }

    /// <summary>The domain-declared standing name.</summary>
    public string Name { get; }

    /// <inheritdoc />
    public override string ToString() => Name;
}

/// <summary>
/// The set-facing Rules shape (DES-0018 <c>rules-ck-21</c>): an ordinary versioned definition that computes a
/// standing from declared fields of one record type. Its predicate is a schema-scoped
/// <c>harborline-jsonlogic/v1</c> validation rule, admitted by the compiler when the definition is made, and
/// its declared inputs are exactly the fields that predicate reads.
/// </summary>
public sealed record StandingRuleDefinition
{
    /// <summary>Creates and validates a standing rule; refuses by <see cref="ArgumentException"/>.</summary>
    public StandingRuleDefinition(string ruleId, string ruleVersion, StandingReference standing, string recordType,
        IReadOnlyList<string> inputFields, RuleDefinition predicate)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(ruleId);
        ArgumentException.ThrowIfNullOrWhiteSpace(ruleVersion);
        ArgumentException.ThrowIfNullOrWhiteSpace(recordType);
        ArgumentNullException.ThrowIfNull(inputFields);
        ArgumentNullException.ThrowIfNull(predicate);
        if (standing == default) throw new ArgumentException("A standing name is required.", nameof(standing));
        if (inputFields.Count == 0 || inputFields.Any(string.IsNullOrWhiteSpace)
            || inputFields.Distinct(StringComparer.Ordinal).Count() != inputFields.Count)
            throw new ArgumentException("Input fields must be one or more unique, non-empty names.", nameof(inputFields));
        RequireValidationShape(predicate);
        if (!string.Equals(predicate.Id, ruleId, StringComparison.Ordinal))
            throw new ArgumentException("The predicate id must equal the standing rule id.", nameof(predicate));
        if (!FieldsRead(predicate).SetEquals(inputFields))
            throw new ArgumentException("Input fields must name exactly the record fields the predicate reads.", nameof(inputFields));

        (RuleId, RuleVersion, Standing, RecordType, InputFields, Predicate) =
            (ruleId, ruleVersion, standing, recordType, inputFields.ToArray(), predicate);
    }

    /// <summary>The stable rule identity evidence and traces name.</summary>
    public string RuleId { get; }

    /// <summary>The installed rule version evidence and traces name.</summary>
    public string RuleVersion { get; }

    /// <summary>The standing carried when the predicate passes.</summary>
    public StandingReference Standing { get; }

    /// <summary>The record type this rule is declared on.</summary>
    public string RecordType { get; }

    /// <summary>The complete set of record fields the predicate reads.</summary>
    public IReadOnlyList<string> InputFields { get; }

    /// <summary>The closed-grammar predicate.</summary>
    public RuleDefinition Predicate { get; }

    // The schema-scoped rule shape, shared with the record-write rules that reuse it (T-978 ruling).
    internal static void RequireValidationShape(RuleDefinition predicate)
    {
        if (predicate.Tier != RuleTier.JsonLogic || predicate.Action != RuleActionKind.Validate || predicate.Scope != RuleScope.Schema)
            throw new ArgumentException("The predicate must be a schema-scoped harborline-jsonlogic/v1 validation rule.", nameof(predicate));
    }

    // Compiles the predicate and returns the top-level record fields it reads; any other reference refuses.
    internal static HashSet<string> FieldsRead(RuleDefinition predicate)
    {
        var references = RuleCompiler.Compile([predicate]).Rules.Single().References;
        if (references.Any(reference => reference is not FieldRef))
            throw new ArgumentException("The predicate may read only top-level record fields.", nameof(predicate));
        return references.OfType<FieldRef>().Select(reference => reference.Name).ToHashSet(StringComparer.Ordinal);
    }
}

using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Environments;
using Harborline.Foundation.RuleEngine.Records;

using Xunit;

namespace Harborline.Foundation.RuleEngine.Tests;

/// <summary>T-978: the Rules stage a Records write runs before commit (DES-0018 rules-eng-13/14, L272, L274).</summary>
public sealed class RecordWriteRulesTests
{
    private static readonly DateTimeOffset At = new(2026, 9, 28, 0, 0, 0, TimeSpan.Zero);

    private static RuleDefinition Rule(string id, string expression, RuleActionKind action = RuleActionKind.Validate)
        => RuleDefinitionFactory.Create(id, RuleTier.JsonLogic, RuleScope.Schema, "", expression, action);

    private static readonly RuleDefinition PositiveRent = Rule("rent-positive", """{">":[{"var":"rent"},0]}""");

    private static JsonObject Record(int rent) => new() { ["rent"] = rent, ["unit"] = "4B" };

    [Fact(DisplayName = "T-978: a record write whose bound rule refuses it is refused with the rule named")]
    public void Violating_write_is_refused_with_the_rule_named()
    {
        var rules = RecordWriteRules.Bind("lease", [PositiveRent]);

        var refusal = rules.Evaluate(Record(0), At);

        Assert.Equal(new RecordRuleRefusal("rent-positive", "rent-positive"), refusal);
    }

    [Fact(DisplayName = "T-978: a record write that satisfies every bound rule passes the stage")]
    public void Satisfying_write_passes()
    {
        var rules = RecordWriteRules.Bind("lease", [PositiveRent, Rule("unit-named", """{"!!":[{"var":"unit"}]}""")]);

        Assert.Null(rules.Evaluate(Record(1200), At));
    }

    [Fact(DisplayName = "T-978: each bound rule is evaluated, so the second rule's refusal is not skipped")]
    public void Every_rule_is_evaluated()
    {
        var rules = RecordWriteRules.Bind("lease", [PositiveRent, Rule("unit-named", """{"!!":[{"var":"unit"}]}""")]);

        Assert.Equal("unit-named", rules.Evaluate(new JsonObject { ["rent"] = 5 }, At)?.RuleId);
    }

    [Fact(DisplayName = "L274: a bound rule that cannot be interpreted during the write refuses it rather than being skipped")]
    public void Uninterpretable_rule_refuses_the_write()
    {
        var rules = RecordWriteRules.Bind("lease", [PositiveRent], RuleEngineLimits.Default with { StepBudget = 1 });

        var refusal = rules.Evaluate(Record(1200), At);

        Assert.NotNull(refusal);
        Assert.Equal("rent-positive", refusal.RuleId);
        Assert.NotEqual("rent-positive", refusal.Code);
    }

    [Fact(DisplayName = "T-978 ruling: a record rule reuses the standing shape, so binding refuses anything but a schema-scoped validation predicate over top-level fields")]
    public void Binding_refuses_a_rule_outside_the_standing_shape()
    {
        Assert.Throws<ArgumentException>(() => RecordWriteRules.Bind("lease", [Rule("c", """{"var":"rent"}""", RuleActionKind.Compute)]));
        Assert.Throws<ArgumentException>(() => RecordWriteRules.Bind("lease",
            [RuleDefinitionFactory.Create("f", RuleTier.JsonLogic, RuleScope.Field, "rent", """{">":[{"var":"rent"},0]}""", RuleActionKind.Validate)]));
        Assert.Throws<ArgumentException>(() => RecordWriteRules.Bind("lease", [Rule("t", """{">":[{"agg":["sum","rows","amount"]},0]}""")]));
        Assert.Throws<ArgumentException>(() => RecordWriteRules.Bind("lease", [Rule("m", """{">":[{"agg":["sum","rows","amount"]},{"var":"rent"}]}""")]));
        Assert.Throws<ArgumentException>(() => RecordWriteRules.Bind("lease", [PositiveRent, PositiveRent]));
        Assert.Throws<ArgumentException>(() => RecordWriteRules.Bind(" ", [PositiveRent]));
        Assert.Throws<ArgumentNullException>(() => RecordWriteRules.Bind("lease", null!));
        Assert.Throws<ArgumentNullException>(() => RecordWriteRules.Bind("lease", [null!]));
        Assert.Throws<ArgumentNullException>(() => RecordWriteRules.Bind("lease", [PositiveRent]).Evaluate(null!, At));
    }

    [Fact(DisplayName = "T-978: rules evaluate in rule-id order whatever order the generation lists them, so the refusal named is deterministic")]
    public void Rules_evaluate_in_rule_id_order()
    {
        var rules = RecordWriteRules.Bind("lease", [Rule("unit-named", """{"!!":[{"var":"unit"}]}"""), PositiveRent]);

        Assert.Equal(["rent-positive", "unit-named"], rules.Rules.Select(rule => rule.Id));
        Assert.Equal("rent-positive", rules.Evaluate(new JsonObject { ["rent"] = 0 }, At)?.RuleId);
        Assert.Equal("lease", rules.RecordType);
    }

    [Fact(DisplayName = "rules-eng-26: the stage evaluates under the Records borrower declaration released as records-auth-12, in its Submission phase")]
    public void Stage_evaluates_under_the_released_records_declaration()
    {
        var fixture = JsonNode.Parse(File.ReadAllText(Path.Combine(FunctionRegisterTests.RepositoryRoot(),
            "conformance", "hlp.foundation.rule-runtime", "borrower-contracts.json")))!["borrowers"]!.AsArray()
            .Single(node => node!["declaration"]!["borrower"]!.GetValue<string>() == "records-auth-12")!;

        Assert.Equal(fixture["canonical"]!.GetValue<string>(), BorrowerEnvironmentAdmission.CanonicalJson(RecordWriteRules.Declaration));
        Assert.Equal(EvaluationPhase.Submission, RecordWriteRules.Phase);
        Assert.Equal(fixture["admittedPhase"]!.GetValue<string>(), RecordWriteRules.Phase.ToString());
    }
}

using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Standings;

using Xunit;

namespace Harborline.Foundation.RuleEngine.Tests;

/// <summary>T-591: the platform standing rule, its store, and authorized set evaluation.</summary>
public sealed class StandingTests
{
    internal static RuleDefinition Predicate(string id, string expression)
        => RuleDefinitionFactory.Create(id, RuleTier.JsonLogic, RuleScope.Schema, "", expression, RuleActionKind.Validate);

    internal static StandingRuleDefinition Rule(string id, string standing, string expression, params string[] inputs)
        => new(id, "1.0.0", new StandingReference(standing), "asset", inputs, Predicate(id, expression));

    [Fact(DisplayName = "rules-ck-21: a standing rule is a schema-scoped validation predicate whose declared inputs name exactly the fields it reads")]
    public void Standing_rule_declares_exactly_the_fields_it_reads()
    {
        var rule = Rule("overdue", "overdue", """{">":[{"var":"daysLate"},30]}""", "daysLate");
        Assert.Equal(["daysLate"], rule.InputFields);
        Assert.Equal("overdue", rule.Standing.Name);

        // An undeclared read, an unread declaration, a non-predicate action and a mismatched id each refuse.
        Assert.Throws<ArgumentException>(() => Rule("a", "s", """{">":[{"var":"daysLate"},{"var":"grace"}]}""", "daysLate"));
        Assert.Throws<ArgumentException>(() => Rule("b", "s", """{">":[{"var":"daysLate"},30]}""", "daysLate", "grace"));
        Assert.Throws<ArgumentException>(() => new StandingRuleDefinition("c", "1.0.0", new StandingReference("s"), "asset", ["x"],
            RuleDefinitionFactory.Create("c", RuleTier.JsonLogic, RuleScope.Schema, "", """{"var":"x"}""", RuleActionKind.Compute)));
        Assert.Throws<ArgumentException>(() => new StandingRuleDefinition("d", "1.0.0", new StandingReference("s"), "asset", ["x"],
            Predicate("other", """{"var":"x"}""")));
    }

    private static readonly DateTimeOffset At = new(2026, 9, 25, 0, 0, 0, TimeSpan.Zero);

    private static StandingRecord Row(string id, string status, int amount)
        => new(id, "asset", new Dictionary<string, JsonNode?> { ["status"] = status, ["amount"] = amount, ["id"] = id });

    private static ValueTask<bool> Everyone(StandingRecord row, CancellationToken ct) => ValueTask.FromResult(true);

    [Fact(DisplayName = "rules-eng-20: 1,000 rows sharing one invariant predicate take one predicate evaluation and yield 1,000 classified outcomes; a distinct-record predicate takes 1,000 and classifies each row by its own value")]
    public async Task Standing_set_evaluation_is_sublinear_in_shared_inputs_and_exact_per_record()
    {
        // Workload stated before running: 1,000 asset rows, all status "open", amounts 0..999.
        var rows = Enumerable.Range(0, 1000).Select(i => Row("a" + i.ToString("D4", System.Globalization.CultureInfo.InvariantCulture), "open", i)).ToArray();
        var open = Rule("open", "open", """{"==":[{"var":"status"},"open"]}""", "status");
        var large = Rule("large", "large", """{">":[{"var":"amount"},500]}""", "amount");
        var evaluator = new StandingEvaluator();

        // Invariant predicate: expect exactly 1 evaluation and 1,000 classified outcomes.
        var shared = await evaluator.EvaluateSetAsync(Grants.All, rows, Everyone, [open], TestAdmission.Any, At, 0, 1000);
        Assert.Equal(1, shared.PredicateEvaluations);
        Assert.Equal(1000, shared.VisibleCount);
        Assert.Equal(1000, shared.Page.Count);
        Assert.All(shared.Page, row => Assert.Equal([new StandingReference("open")], row.Standings));
        Assert.Equal(1000, shared.Counts[new StandingReference("open")]);

        // Distinct-record predicate: a cache keyed on anything but the rule's inputs would misclassify here.
        var distinct = await evaluator.EvaluateSetAsync(Grants.All, rows, Everyone, [large], TestAdmission.Any, At, 0, 1000);
        Assert.Equal(1000, distinct.PredicateEvaluations);
        Assert.Equal(499, distinct.Counts[new StandingReference("large")]);
        Assert.Empty(distinct.Page.Single(row => row.RecordId == "a0500").Standings);
        Assert.Equal([new StandingReference("large")], distinct.Page.Single(row => row.RecordId == "a0501").Standings);

        var both = await evaluator.EvaluateSetAsync(Grants.All, rows, Everyone, [open, large], TestAdmission.Any, At, 0, 10);
        Assert.Equal(1001, both.PredicateEvaluations);
        Assert.Equal(2, both.Page[0].Decisions.Count);
    }

    [Fact(DisplayName = "rules-eng-20: interleaved unauthorized rows are removed before standing evaluation, counting and paging, so they never alter visible counts, pages or the evaluation count")]
    public async Task Unauthorized_rows_never_reach_standing_evaluation_counts_or_pages()
    {
        var authorized = Enumerable.Range(0, 1000).Select(i => Row("a" + i.ToString("D4", System.Globalization.CultureInfo.InvariantCulture), "open", i)).ToArray();
        // Each denied row carries the standing with a value no authorized row has.
        var interleaved = authorized.SelectMany((row, i) => new[] { Row("d" + i.ToString("D4", System.Globalization.CultureInfo.InvariantCulture), "open", 5000 + i), row }).ToArray();
        var large = Rule("large", "large", """{">":[{"var":"amount"},500]}""", "amount");
        var evaluator = new StandingEvaluator();
        ValueTask<bool> Access(StandingRecord row, CancellationToken ct) => ValueTask.FromResult(row.RecordId.StartsWith('a', StringComparison.Ordinal));

        var expected = await evaluator.EvaluateSetAsync(Grants.All, authorized, Everyone, [large], TestAdmission.Any, At, 490, 20);
        var actual = await evaluator.EvaluateSetAsync(Grants.All, interleaved, Access, [large], TestAdmission.Any, At, 490, 20);

        Assert.Equal(1000, actual.VisibleCount);
        Assert.Equal(expected.Counts[new StandingReference("large")], actual.Counts[new StandingReference("large")]);
        Assert.Equal(expected.Page.Select(row => row.RecordId), actual.Page.Select(row => row.RecordId));
        Assert.Equal(1000, actual.PredicateEvaluations);
    }

    [Fact(DisplayName = "rules-eng-26: standing set evaluation refuses without admission before reading any row")]
    public async Task Standing_set_evaluation_requires_admission()
    {
        var rule = Rule("open", "open", """{"==":[{"var":"status"},"open"]}""", "status");
        var result = await new StandingEvaluator().EvaluateSetAsync(Grants.All, [Row("a", "open", 1)], Everyone, [rule], null, At, 0, 10);
        var decision = Assert.Single(Assert.Single(result.Page).Decisions);
        Assert.False(decision.Carries);
        Assert.Equal(Environments.BorrowerEnvironmentAdmission.NotAdmitted, decision.RefusalCode);
    }
}

/// <summary>Host-supplied Access verdicts over capability names (test double for the host gate).</summary>
internal static class Grants
{
    public static RulesCapabilityCheck All { get; } = (_, _) => ValueTask.FromResult(true);

    public static RulesCapabilityCheck Only(params string[] granted)
        => (permission, _) => ValueTask.FromResult(granted.Contains(permission, StringComparer.Ordinal));
}

/// <summary>T-591 (owner ruling Q14): the Rules capability names and the evaluate/explain boundary.</summary>
public sealed class RulesPermissionTests
{
    private static readonly DateTimeOffset At = new(2026, 9, 25, 0, 0, 0, TimeSpan.Zero);

    [Fact(DisplayName = "rules-auth-34: Rules declares exactly four permissions, rules:author, rules:publish, rules:author-floor and rules:evaluate-explain, and seeds no role grants")]
    public void Rules_declares_its_four_capabilities()
        => Assert.Equal(["rules:author", "rules:publish", "rules:author-floor", "rules:evaluate-explain"], RulesPermissions.All);

    [Theory(DisplayName = "rules-eng-20: standing set evaluation needs both rules:evaluate-explain and records:read at the operation boundary, and refuses before any row is authorized or read")]
    [InlineData("rules:evaluate-explain")]
    [InlineData("records:read")]
    public async Task Standing_evaluation_needs_evaluate_explain_and_records_read(string only)
    {
        var rule = StandingTests.Rule("open", "open", """{"==":[{"var":"status"},"open"]}""", "status");
        var row = new StandingRecord("a", "asset", new Dictionary<string, JsonNode?> { ["status"] = "open" });
        int rowChecks = 0;
        ValueTask<bool> Count(StandingRecord record, CancellationToken ct) { rowChecks++; return ValueTask.FromResult(true); }
        var evaluator = new StandingEvaluator();

        var refused = await Assert.ThrowsAsync<RulesPermissionException>(async () =>
            await evaluator.EvaluateSetAsync(Grants.Only(only), [row], Count, [rule], TestAdmission.Any, At, 0, 10));
        Assert.Equal(RulesPermissions.DeniedCode, refused.Code);
        Assert.Equal(0, rowChecks);

        var allowed = await evaluator.EvaluateSetAsync(Grants.Only(RulesPermissions.EvaluateExplain, RulesPermissions.RecordsRead), [row], Count, [rule], TestAdmission.Any, At, 0, 10);
        Assert.Equal(1, allowed.VisibleCount);
    }

    [Theory(DisplayName = "rules-eng-19: the standing evidence read needs both rules:evaluate-explain and records:read before its own evidence-read check")]
    [InlineData("rules:evaluate-explain")]
    [InlineData("records:read")]
    public async Task Evidence_read_needs_evaluate_explain_and_records_read(string only)
    {
        var rule = StandingTests.Rule("open", "open", """{"==":[{"var":"status"},"open"]}""", "status");
        var row = new StandingRecord("a", "asset", new Dictionary<string, JsonNode?> { ["status"] = "open" });
        static ValueTask<bool> Allow(StandingRecord record, CancellationToken ct) => ValueTask.FromResult(true);
        var evaluator = new StandingEvaluator();

        Assert.Equal(StandingEvidenceAvailability.Refused,
            (await evaluator.ReadEvidenceAsync(Grants.Only(only), row, rule, Allow, TestAdmission.Any, At)).Availability);
        Assert.Equal(StandingEvidenceAvailability.Available,
            (await evaluator.ReadEvidenceAsync(Grants.Only(RulesPermissions.EvaluateExplain, RulesPermissions.RecordsRead), row, rule, Allow, TestAdmission.Any, At)).Availability);
    }
}
